let rows=[],stop=false,busy=false,fail=new Map(),mode='all',rootDir=null,rootDirIsRace=false,archiveKeys=new Set(),archiveFileCount=0,archiveUnmatched=0,archiveScanOk=false;const DIR_DB='at_ai_m8_dir_v1';
const ARCHIVE_REFRESH_DAYS=1;function stamp(v){let t=Date.parse(v||'');return Number.isFinite(t)?t:0}function archiveFresh(doc,days=ARCHIVE_REFRESH_DAYS){let t=stamp(doc?.lastChecked||doc?.lastUpdated||doc?.savedAt||doc?.data?.lastChecked||doc?.data?.lastUpdated);return !!t&&(Date.now()-t)<days*86400000}
