async function resolveHorseRaces(atId,opt={}){let h=await getHorseHistory(atId,opt),src=h?.record?.data||h?.record||{},list=src.races||[],out=[];for(const r of list){if(!r.date||!r.city)continue;let a=await readArchive(r.date,r.city);if(a){out.push({history:r,archiveSource:'phone',archive:a});continue}let legacy=await get(r.date+'|'+r.city);if(legacy)out.push({history:r,archiveSource:'indexeddb',archive:legacy});else out.push({history:r,archiveSource:'missing',archive:null})}return{atId:String(atId),historySource:h.source,total:list.length,matched:out.filter(x=>x.archive).length,missing:out.filter(x=>!x.archive).length,races:out}}
function fogdYear(data){let v=data?.raceDate||data?.data?.raceDate||data?.savedAt||'';let m=String(v).match(/(20\\d{2})/);return m?m[1]:String(new Date().getFullYear())}
