function numField(r,names){for(const n of names){let v=r?.[n];if(v==null)continue;let m=String(v).replace(',','.').match(/\d+(?:\.\d+)?/);if(m)return Number(m[0])}return null}
function textField(r,names){for(const n of names){let v=String(r?.[n]??'').trim();if(v)return v}return''}
function normName(v){return String(v||'').normalize('NFC').replace(/\s+/g,' ').trim().toLocaleUpperCase('tr-TR')}
