async function findHorseArchiveByName(name){let target=normName(name);if(!target)return null;try{let d=await horseArchiveDir(false);for await(const [fn,fh] of d.entries()){if(fh.kind!=='file'||!fn.endsWith('.json'))continue;let file=await fh.getFile(),j=JSON.parse(await file.text());if(normName(j.name)===target)return j}}catch{}return null}
async function analyzeOriginLineage(section,name,targetDistance,track=''){let doc=await originLineageFile(section,name),rows=doc?.rows||[];if(!rows.length)return{ok:false,error:'Orijin soy arşivi bulunamadı',section,name};let childNames=[...new Set(rows.map(lineageChildName).filter(Boolean).map(x=>x.trim()))],bands=[0,100,200,300,400],out={};for(const b of bands)out[b]={starts:0,children:0,first:0,top3:0,records:[]};let matchedChildren=0,missingChildren=[];for(const child of childNames){let h=await findHorseArchiveByName(child);if(!h){missingChildren.push(child);continue}matchedChildren++;let used=new Set();for(const r of h.races||[]){let dist=horseRaceDistance(r);if(!dist)continue;if(track&&normName(horseRaceTrack(r))!==normName(track))continue;let delta=Math.abs(dist-Number(targetDistance));for(const b of bands){if(delta>b)continue;let o=out[b];o.starts++;used.add(b);let place=numField(r,['rank','place','finish','sıra','Sıra','Derece Sırası']);if(place===1)o.first++;if(place&&place<=3)o.top3++;o.records.push({horse:h.name,horseId:h.horseId,distance:dist,delta,track:horseRaceTrack(r),place,date:r.date||''})}}for(const b of used)out[b].children++}return{ok:true,version:'ORIGIN-ARCHIVE-MATCH-V1',section,name,targetDistance:Number(targetDistance),track:track||null,originChildren:childNames.length,matchedChildren,missingChildren:missingChildren.length,bands:out}}
