async function saveFile(r,j){if(!rootDir)throw Error('Önce AT AI MOBIL klasörünü seçin');let p=await rootDir.queryPermission({mode:'readwrite'});if(p!=='granted')p=await rootDir.requestPermission({mode:'readwrite'});if(p!=='granted')throw Error('Klasör yazma izni yok');let race=rootDirIsRace?rootDir:await rootDir.getDirectoryHandle('Gerçek Yarış Arşivi',{create:true}),yr=await race.getDirectoryHandle(r.date.slice(0,4),{create:true}),name=r.date+'_'+r.city.replace(/[^a-zA-Z0-9ğüşöçıİĞÜŞÖÇ_-]+/g,'_')+'.json',fh=await yr.getFileHandle(name,{create:true}),w=await fh.createWritable();await w.write(JSON.stringify({version:'F60.94.31.52',savedAt:new Date().toISOString(),date:r.date,city:r.city,count:r.count,data:j},null,2));await w.close();return name}
async function dl(r){let id=C[r.city];if(!id)throw Error('Şehir ID yok');if(!rootDir)throw Error('Önce AT AI MOBIL klasörünü seçin');let x=await fetch('/api/tjk-day-results-v1?date='+r.date+'&cityId='+id+'&city='+encodeURIComponent(r.city),{cache:'no-store'}),j=await x.json();if(!j.ok)throw Error(j.error||'İndirme hatası');let file=await saveFile(r,j);await put({key:r.key,date:r.date,city:r.city,count:r.count,file,at:Date.now()});fail.delete(r.key)}
