function filtered(){let l=baseRows();if(mode==='missing')return l.filter(r=>!archiveKeys.has(archiveKey(r.date,r.city)));if(mode==='failed')return l.filter(r=>fail.has(r.key));return l}
function setMode(v){mode=v;render()}
async function refreshArchiveState(){let l=baseRows(),existing=l.filter(r=>archiveKeys.has(archiveKey(r.date,r.city))).length,missing=l.length-existing;m8missing.textContent=missing;m8errors.textContent=fail.size;m8showmissing.textContent='⬇ Eksik / İndirilmeyenler ('+missing+')';m8showfail.textContent='⚠ Hatalar ('+fail.size+')';return{existing,missing,total:l.length}}
async function render(){let h=m8rows,l=filtered();h.innerHTML='';for(const r of l){let done=archiveKeys.has(archiveKey(r.date,r.city)),er=fail.get(r.key),d=document.createElement('div');d.className='m8row';d.innerHTML='<span class="m8date">'+e(r.date.split('-').reverse().join('.'))+'</span><span class="m8city">'+e(r.city)+'</span><span class="m8cnt">'+r.count+'K</span><span class="m8st">'+(done?'✓':er?'⚠':'—')+'</span><button class="secondary small">'+(done?'Mevcut':'İndir')+'</button>'+(er?'<small class="m8err">'+e(er)+'</small>':'');d.querySelector('button').disabled=done;d.querySelector('button').onclick=async()=>{try{await dl(r);archiveKeys.add(archiveKey(r.date,r.city));fail.delete(r.key)}catch(x){fail.set(r.key,x.message)}await refreshArchiveState();render()};h.appendChild(d)}let s=await refreshArchiveState();m8sum.textContent=(mode==='missing'?'Eksik kayıt: '+s.missing:mode==='failed'?'Hatalı kayıt: '+fail.size:'Klasör '+archiveFileCount+' dosya · Toplam '+s.total+' · Mevcut '+s.existing+' · Eksik '+s.missing+' · Hata '+fail.size)}
